/bin/bash -lc "python - <<'PY'
from pathlib import Path
for label,path in [('full','/workspace/galaxy_downloads/full_deseq.tsv'),('reduced','/workspace/galaxy_downloads/reduced_deseq.tsv')]:
  n=0
  with open(path,encoding='utf-8') as f:
    for line in f:
      x=line.rstrip('\\n').split('\\t')
      if len(x)>=6:
        try:
          if float(x[1])>10 and abs(float(x[2]))>1 and float(x[5])<0.05: n+=1
        except ValueError: pass
  print(label,n)
PY"

